#ifndef EQEMU_HOUSING_ITEM_PAYLOAD_DB_H
#define EQEMU_HOUSING_ITEM_PAYLOAD_DB_H
#include "inventory_row_db.h"
#include "legacy_scaling_state.h"
#include "evolving_item_custody_db.h"
#include "../database.h"
#include "../inventory_profile.h"
#include <algorithm>
#include <map>
#include <set>
namespace Housing::ItemPayload {
inline auto Query(Database& db,const std::string& sql){auto rows=db.QueryDatabase(sql,false);if(!rows.Success())throw std::invalid_argument("Housing item payload query failed");return rows;}
inline std::string Where(uint32_t owner,uint32_t slot){return "character_id="+std::to_string(owner)+" AND slot_id="+std::to_string(slot);}
inline uint32_t ChildSlot(uint32_t parent,uint32_t child){if(child>=CustodyCodec::MaximumBagSlots)throw std::invalid_argument("Invalid native bag slot");const auto slot=EQ::InventoryProfile::CalcSlotId(int16_t(parent),uint8_t(child));if(slot<0)throw std::invalid_argument("Unsupported housing bag parent slot");return uint32_t(slot);}
inline void Metadata(Database& db,const LiveItems::InventoryRow& row,bool child=false){
 if(!CustodyCodec::Valid(row)||!row.values.item_id||row.null_fields&LiveItems::NullItemId)throw std::invalid_argument("Invalid housing item payload");
 const auto& v=row.values;auto rows=Query(db,"SELECT itemclass,bagslots,notransfer,charmfileid FROM items WHERE id="+std::to_string(v.item_id)+" FOR UPDATE");if(rows.RowCount()!=1)throw std::invalid_argument("Missing housing payload item");auto m=rows.begin();for(unsigned i=0;i<4;++i)if(!m[i])throw std::invalid_argument("Missing item payload metadata");auto kind=std::stoul(m[0]),bags=std::stoul(m[1]);if(kind>2||bags>CustodyCodec::MaximumBagSlots||(kind!=1&&bags)||(child&&!row.children.empty())||(!row.children.empty()&&(kind!=1||!bags)))throw std::invalid_argument("Unsupported native bag contents");
 if(kind!=0&&(v.augment_one||v.augment_two||v.augment_three||v.augment_four||v.augment_five||v.augment_six))throw std::invalid_argument("Non-common item cannot own augment sockets");
 for(auto id:{v.augment_one,v.augment_two,v.augment_three,v.augment_four,v.augment_five,v.augment_six})if(id){auto a=Query(db,"SELECT itemclass,augtype,bagslots,charmfileid FROM items WHERE id="+std::to_string(id)+" FOR UPDATE");if(a.RowCount()!=1||!a.begin()[0]||std::string(a.begin()[0])!="0"||!a.begin()[1]||std::stoull(a.begin()[1])==0||!a.begin()[2]||std::string(a.begin()[2])!="0"||!a.begin()[3])throw std::invalid_argument("Invalid housing augment identity");}
 const std::array<uint32_t,7> components{v.item_id,v.augment_one,v.augment_two,v.augment_three,v.augment_four,v.augment_five,v.augment_six};auto evolving=EvolvingItemCustody::Decode(row.evolving_payload);std::array<uint32_t,7> scaling{};
 for(unsigned i=0;i<components.size();++i)if(components[i]){auto m=Query(db,"SELECT evoitem,charmfileid FROM items WHERE id="+std::to_string(components[i])+" FOR UPDATE");if(m.RowCount()!=1||!m.begin()[0]||!m.begin()[1])throw std::invalid_argument("Missing evolving item definition");auto details=Query(db,"SELECT id FROM items_evolving_details WHERE item_id="+std::to_string(components[i])+" FOR UPDATE");if(std::stoll(m.begin()[1])!=0)scaling[i]=components[i];const bool required=std::stoul(m.begin()[0])||details.RowCount();auto state=std::find_if(evolving.begin(),evolving.end(),[&](const auto& e){return e.component==i;});if(required!=(state!=evolving.end())||(state!=evolving.end()&&(state->owner!=v.character_id||state->item!=components[i])))throw std::invalid_argument("Incomplete evolving component custody");}
 if(!LegacyScaling::Metadata(v.custom_data,scaling))throw std::invalid_argument("Incomplete legacy scaling component custody");
 for(const auto& state:evolving)if(!components[state.component])throw std::invalid_argument("Orphan evolving augment custody");
 for(const auto& content:row.children){if(content.values.slot_id>=bags)throw std::invalid_argument("Bag content exceeds original slot limit");auto c=Query(db,"SELECT notransfer FROM items WHERE id="+std::to_string(content.values.item_id)+" FOR UPDATE");if(c.RowCount()!=1||!c.begin()[0]||std::string(c.begin()[0])!="0")throw std::invalid_argument("Bag content cannot enter housing storage");Metadata(db,content,true);}
}
// The caller's expected evolving bytes are identity witnesses, never an SQL
// substitute. The evolving ownership module verifies them on the same TX.
inline LiveItems::InventoryRow Complete(Database& db,LiveItems::InventoryRow root,const LiveItems::InventoryRow* expected=nullptr){
 if(expected)root.evolving_payload=expected->evolving_payload;
 if(root.values.slot_id<23||root.values.slot_id>33){if(expected&&!expected->children.empty())throw std::invalid_argument("Unsupported nested housing inventory source");return root;}
 const auto first=ChildSlot(root.values.slot_id,0),last=ChildSlot(root.values.slot_id,CustodyCodec::MaximumBagSlots-1);auto rows=Query(db,"SELECT "+std::string(InventoryRowDB::Columns)+" FROM inventory WHERE character_id="+std::to_string(root.values.character_id)+" AND slot_id BETWEEN "+std::to_string(first)+" AND "+std::to_string(last)+" ORDER BY slot_id FOR UPDATE");
 for(auto row=rows.begin();row!=rows.end();++row){auto content=InventoryRowDB::Decode(row);content.values.slot_id-=first;if(expected){auto e=std::find_if(expected->children.begin(),expected->children.end(),[&](const auto& child){return child.values.slot_id==content.values.slot_id;});if(e!=expected->children.end())content.evolving_payload=e->evolving_payload;}root.children.push_back(std::move(content));}
 if(!CustodyCodec::Valid(root))throw std::invalid_argument("Invalid canonical housing payload");return root;
}
inline LiveItems::InventoryRow Read(Database& db,uint32_t owner,uint32_t slot,const LiveItems::InventoryRow* expected=nullptr){auto r=Query(db,"SELECT "+std::string(InventoryRowDB::Columns)+" FROM inventory WHERE "+Where(owner,slot)+" FOR UPDATE");if(r.RowCount()!=1)throw std::invalid_argument("Housing inventory payload missing");return Complete(db,InventoryRowDB::Decode(r.begin()),expected);}
inline void Insert(Database& db,const LiveItems::InventoryRow& root){
 if(!CustodyCodec::Valid(root))throw std::invalid_argument("Invalid housing inventory write");auto one=[&](const LiveItems::InventoryRow& row,uint32_t slot){auto r=Query(db,"INSERT INTO inventory("+std::string(InventoryRowDB::WriteColumns)+") VALUES("+InventoryRowDB::Values(row,slot)+")");if(r.RowsAffected()!=1)throw std::invalid_argument("Housing inventory payload insert failed");};one(root,root.values.slot_id);for(const auto& child:root.children)one(child,ChildSlot(root.values.slot_id,child.values.slot_id));
}
inline void RemoveChildren(Database& db,const LiveItems::InventoryRow& root){for(const auto& child:root.children){auto r=Query(db,"DELETE FROM inventory WHERE "+Where(root.values.character_id,ChildSlot(root.values.slot_id,child.values.slot_id)));if(r.RowsAffected()!=1)throw std::invalid_argument("Housing source contents changed");}}
inline void Owner(LiveItems::InventoryRow& row,uint32_t owner){row.values.character_id=owner;if(!row.evolving_payload.empty()){auto states=EvolvingItemCustody::Decode(row.evolving_payload);for(auto& state:states)state.owner=owner;row.evolving_payload=EvolvingItemCustody::Encode(states);}for(auto& child:row.children)Owner(child,owner);}
inline void Capture(Database& db,LiveItems::InventoryRow& row,EQ::ItemInstance& item){row.evolving_payload=EvolvingItemCustody::Capture(db,row.values.character_id,row.values.slot_id,item);for(auto& child:row.children){auto found=item.GetContents()->find(uint8_t(child.values.slot_id));if(found==item.GetContents()->end()||!found->second)throw std::invalid_argument("Missing runtime bag child identity");child.evolving_payload=EvolvingItemCustody::Capture(db,row.values.character_id,ChildSlot(row.values.slot_id,child.values.slot_id),*found->second);}}
inline void ValidateInventory(Database& db,const LiveItems::InventoryRow& row){EvolvingItemCustody::ValidateInventory(db,row.evolving_payload,row.values.character_id,row.values.slot_id);for(const auto& child:row.children)EvolvingItemCustody::ValidateInventory(db,child.evolving_payload,child.values.character_id,ChildSlot(row.values.slot_id,child.values.slot_id));}
inline void Hold(Database& db,const LiveItems::InventoryRow& row,uint64_t custody){EvolvingItemCustody::StoreHold(db,row.evolving_payload,custody,0);for(const auto& child:row.children)EvolvingItemCustody::StoreHold(db,child.evolving_payload,custody,child.values.slot_id+1);}
inline void ValidateHeld(Database& db,const LiveItems::InventoryRow& row,uint64_t custody){EvolvingItemCustody::ValidateHeld(db,row.evolving_payload,custody,0);for(const auto& child:row.children)EvolvingItemCustody::ValidateHeld(db,child.evolving_payload,custody,child.values.slot_id+1);}
// Use the immutable held/source row, before Owner normalization. Release owns
// the CEI location transition inside the caller's inventory insertion TX.
inline LiveItems::InventoryRow Release(Database& db,const LiveItems::InventoryRow& before,uint64_t custody,uint32_t owner,uint32_t slot){auto out=before;out.evolving_payload=EvolvingItemCustody::ReturnRelease(db,before.evolving_payload,custody,0,owner,slot,before.values.guid);for(auto& child:out.children)child.evolving_payload=EvolvingItemCustody::ReturnRelease(db,child.evolving_payload,custody,child.values.slot_id+1,owner,ChildSlot(slot,child.values.slot_id),child.values.guid);Owner(out,owner);out.values.slot_id=slot;return out;}
// Every contained item and installed augment participates in offline collision
// checks. The caller still owns recipient/account and property authority.
inline std::vector<uint32_t> ItemIds(const LiveItems::InventoryRow& row){std::vector<uint32_t> ids{row.values.item_id};for(auto n:{row.values.augment_one,row.values.augment_two,row.values.augment_three,row.values.augment_four,row.values.augment_five,row.values.augment_six})if(n)ids.push_back(n);for(const auto& child:row.children){auto nested=ItemIds(child);ids.insert(ids.end(),nested.begin(),nested.end());}return ids;}
inline std::set<uint64_t> Guids(const LiveItems::InventoryRow& row){std::set<uint64_t> result;if(!(row.null_fields&LiveItems::NullGuid)&&row.values.guid)result.insert(row.values.guid);for(const auto& child:row.children)for(auto n:Guids(child))if(!result.insert(n).second)throw std::invalid_argument("Duplicate custody GUID inside bag");return result;}
inline CustodyCodec::Bytes Unhex(const char* raw){if(!raw)throw std::invalid_argument("Missing custody capsule");std::string text=raw;if(text.size()%2||text.size()>2*CustodyCodec::MaximumPayload)throw std::invalid_argument("Custody capsule bound");auto nib=[](char c){if(c>='0'&&c<='9')return c-'0';if(c>='A'&&c<='F')return c-'A'+10;if(c>='a'&&c<='f')return c-'a'+10;throw std::invalid_argument("Custody capsule hex");};CustodyCodec::Bytes bytes;for(size_t i=0;i<text.size();i+=2)bytes.push_back(uint8_t(nib(text[i])*16+nib(text[i+1])));return bytes;}
inline void Collisions(Database& db,const LiveItems::InventoryRow& row,uint32_t owner,uint32_t account,uint64_t excluded_custody){
 const auto guids=Guids(row);std::set<std::pair<int32_t,uint32_t>> lore;
 const auto signature=[&](uint32_t item)->std::optional<std::pair<int32_t,uint32_t>>{auto r=Query(db,"SELECT loregroup FROM items WHERE id="+std::to_string(item)+" FOR UPDATE");if(r.RowCount()!=1||!r.begin()[0])throw std::invalid_argument("Missing custody lore metadata");auto group=int32_t(std::stoll(r.begin()[0]));if(!group)return {};return std::make_pair(group,group==-1?item:0u);};
 for(auto item:ItemIds(row))if(auto key=signature(item);key){if(!lore.insert(*key).second)throw std::invalid_argument("Duplicate lore members in housing bag");const auto predicate=key->first==-1?"m.id="+std::to_string(item):"m.loregroup="+std::to_string(key->first);for(const auto& table:{std::string("inventory"),std::string("sharedbank")}){const auto authority=table=="inventory"?"i.character_id="+std::to_string(owner):"i.account_id="+std::to_string(account);auto r=Query(db,"SELECT i.slot_id FROM "+table+" i JOIN items m ON m.id IN(i.item_id,i.augment_one,i.augment_two,i.augment_three,i.augment_four,i.augment_five,i.augment_six) WHERE "+authority+" AND "+predicate+" LIMIT 1 FOR UPDATE");if(r.RowCount())throw std::invalid_argument("Housing return lore collision");}}
 for(auto guid:guids)for(const auto& table:{std::string("inventory"),std::string("sharedbank")})if(Query(db,"SELECT slot_id FROM "+table+" WHERE guid="+std::to_string(guid)+" LIMIT 1 FOR UPDATE").RowCount())throw std::invalid_argument("Housing return GUID collision");
 if(guids.empty()&&lore.empty())return;
 auto held=Query(db,"SELECT owner_character_id,HEX(row_blob) FROM housing_live_item_custody WHERE custody_id<>"+std::to_string(excluded_custody)+" ORDER BY custody_id LIMIT 10001 FOR UPDATE");if(held.RowCount()>10000)throw std::invalid_argument("Housing collision census bound");size_t total=0;
 for(auto r=held.begin();r!=held.end();++r){auto raw=Unhex(r[1]);total+=raw.size();if(total>16*CustodyCodec::MaximumPayload)throw std::invalid_argument("Housing collision payload census bound");auto other=CustodyCodec::Decode(raw);for(auto guid:Guids(other))if(guids.count(guid))throw std::invalid_argument("Housing held GUID collision");if(r[0]&&std::stoull(r[0])==owner)for(auto item:ItemIds(other))if(auto key=signature(item);key&&lore.count(*key))throw std::invalid_argument("Housing held lore collision");}
}

}
#endif
